parameters.jsCode:
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body || {};

const authHeader = headers.authorization || headers.Authorization || body.token || '';
let token = authHeader.replace(/^Bearer /i, '').trim();

if (!token) {
  return [{ json: { error: true, statusCode: 401, message: 'Unauthorized.' } }];
}

let decoded;
try {
  decoded = JSON.parse(Buffer.from(token, 'base64').toString('utf8'));
} catch(e) {
  return [{ json: { error: true, statusCode: 401, message: 'Invalid token.' } }];
}

if (decoded.role !== 'ADMIN') {
  return [{ json: { error: true, statusCode: 403, message: 'Forbidden. Admin privileges required.' } }];
}

const orderId = (body.orderId || '').trim();
const newStatus = (body.newStatus || '').trim();
const remarks = (body.remarks || '').trim() || 'Status updated by Admin';

const validStatuses = [
  'Order Submitted',
  'Production Planned',
  'Production Completed',
  'Invoice Generated',
  'Dispatched',
  'Out for Delivery',
  'Delivered',
  'Cancelled'
];

if (!orderId || !validStatuses.includes(newStatus)) {
  return [{ json: { error: true, statusCode: 400, message: 'Valid Order ID and recognized status are required.' } }];
}

return [{
  json: {
    adminId: decoded.userId,
    adminName: decoded.username,
    orderId,
    newStatus,
    remarks
  }
}];

